SELECT task_name, status, count(*) FROM procrastinate.procrastinate_jobs WHERE status IN ('doing','todo') GROUP BY 1,2;
SELECT j.id, j.status, to_char(s.at,'HH24:MI:SS') started, to_char(f.at,'HH24:MI:SS') ended, round(extract(epoch from f.at - s.at)) secs FROM procrastinate.procrastinate_jobs j LEFT JOIN LATERAL (SELECT at FROM procrastinate.procrastinate_events e WHERE e.job_id=j.id AND e.type='started' ORDER BY at LIMIT 1) s ON true LEFT JOIN LATERAL (SELECT at FROM procrastinate.procrastinate_events e WHERE e.job_id=j.id AND e.type IN ('succeeded','failed') ORDER BY at DESC LIMIT 1) f ON true WHERE j.task_name='process_event_revisions' AND s.at > now() - interval '30 minutes' ORDER BY s.at DESC LIMIT 6;
